<?php
declare(strict_types=1);
if(is_file(__DIR__.'/private/installed.lock')){http_response_code(403);exit('La instalación ya está completa. Abre index.php.');}
if(!in_array($_SERVER['REMOTE_ADDR']??'',['127.0.0.1','::1'],true)){http_response_code(403);exit('La instalación debe ejecutarse desde localhost en el equipo servidor.');}
session_start();if(empty($_SESSION['install_csrf']))$_SESSION['install_csrf']=bin2hex(random_bytes(32));
$error='';$done=false;
function h($v): string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
if($_SERVER['REQUEST_METHOD']==='POST')try{
 if(!hash_equals($_SESSION['install_csrf'],$_POST['csrf']??''))throw new RuntimeException('La sesión del instalador venció. Actualiza la página.');
 if(PHP_VERSION_ID<80100||!extension_loaded('pdo_mysql'))throw new RuntimeException('Se requiere PHP 8.1 o superior con PDO MySQL habilitado.');
 $host=trim($_POST['host']??'127.0.0.1');$port=(int)($_POST['port']??3306);$database=trim($_POST['database']??'nobel_asistencia');$dbuser=trim($_POST['dbuser']??'root');$dbpassword=$_POST['dbpassword']??'';$email=strtolower(trim($_POST['adminemail']??''));$password=$_POST['adminpassword']??'';
 if(!preg_match('/^[a-zA-Z][a-zA-Z0-9_]{0,63}$/',$database)||$port<1||$port>65535)throw new RuntimeException('Nombre de base o puerto inválido.');
 if(!preg_match('/^[a-zA-Z0-9.:-]{1,120}$/',$host)||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8)throw new RuntimeException('Comprueba el servidor, correo y contraseña de al menos 8 caracteres.');
 $db=new PDO('mysql:host='.$host.';port='.$port.';charset=utf8mb4',$dbuser,$dbpassword,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false]);
 $db->exec('CREATE DATABASE IF NOT EXISTS `'.$database.'` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci');$db->exec('USE `'.$database.'`');
 foreach(preg_split('/;\s*/',file_get_contents(__DIR__.'/database/schema.sql')) as $sql){if(trim($sql)!=='')$db->exec($sql);}
 require __DIR__.'/private/migrations.php';migrate_manual($db);
 $st=$db->prepare('SELECT id FROM users WHERE id=?');$st->execute(['primary-admin']);if(!$st->fetch()){$st=$db->prepare('INSERT INTO users(id,username,email,name,role,active,password_hash) VALUES(?,?,?,?,?,1,?)');$st->execute(['primary-admin',$email,$email,'Administrador institucional','admin',password_hash($password,PASSWORD_DEFAULT)]);}
 $config=['host'=>$host,'port'=>$port,'database'=>$database,'user'=>$dbuser,'password'=>$dbpassword];
 if(file_put_contents(__DIR__.'/private/config.php',"<?php\nreturn ".var_export($config,true).";\n",LOCK_EX)===false)throw new RuntimeException('No se pudo escribir private/config.php. Revisa los permisos de la carpeta.');
 if(file_put_contents(__DIR__.'/private/installed.lock',gmdate('c'),LOCK_EX)===false)throw new RuntimeException('No se pudo bloquear el instalador. Revisa los permisos.');
 $done=true;unset($_SESSION['install_csrf']);session_regenerate_id(true);
}catch(Throwable $e){error_log('SCAE install: '.$e->getMessage());$error=$e instanceof PDOException?'No se pudo conectar o crear la base. Inicia MySQL en XAMPP y comprueba el usuario, contraseña y puerto.':$e->getMessage();}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Instalar SCAE Nobel</title><style>body{margin:0;background:#f3f6fa;color:#17354c;font:15px 'Segoe UI',sans-serif;padding:30px}main{max-width:700px;margin:auto;background:white;border-radius:18px;padding:32px;box-shadow:0 10px 40px #17354c15}img{width:90px;display:block;margin:auto}h1{text-align:center}label{display:block;font-size:13px;font-weight:600;margin:15px 0 6px}input{box-sizing:border-box;width:100%;padding:12px;border:1px solid #dce5eb;border-radius:8px;font:inherit}.grid{display:grid;grid-template-columns:1fr 1fr;gap:0 20px}.button{display:block;text-align:center;background:#0ea995;color:white;border:0;border-radius:10px;padding:14px;width:100%;margin-top:24px;text-decoration:none;font:inherit}.notice{background:#e6f7f2;padding:18px;border-radius:10px;line-height:1.7}.error{background:#ffecec;color:#a53535;padding:14px;border-radius:8px}p{line-height:1.7;color:#718597}@media(max-width:550px){.grid{display:block}body{padding:15px}main{padding:20px}}</style><link rel="stylesheet" href="assets/buttons.css?v=20261016"><link rel="stylesheet" href="assets/accessibility.css?v=20261023r2"></head><body><main><img src="assets/logo-iestpan.jpg" alt="Logo Alfred Nobel"><h1>Instalación de SCAE</h1><?php if($done): ?><div class="notice">Instalación completada.<br><strong>Usuario: <?=h($email)?></strong><br>Contraseña: la que definiste, si la cuenta es nueva. Si ya existía, conserva su contraseña anterior.<br>No se pide código para iniciar sesión.</div><a class="button" href="index.php">Abrir sistema →</a><?php else: ?><p>Inicia Apache y MySQL en XAMPP. El instalador creará la base, las tablas y el administrador principal sin borrar datos existentes.</p><?php if($error): ?><div class="error"><?=h($error)?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?=h($_SESSION['install_csrf'])?>"><div class="grid"><div><label>Servidor MySQL</label><input name="host" required value="<?=h($_POST['host']??'127.0.0.1')?>"></div><div><label>Puerto MySQL</label><input name="port" type="number" required value="<?=h($_POST['port']??'3306')?>"></div><div><label>Base de datos</label><input name="database" required value="<?=h($_POST['database']??'nobel_asistencia')?>"></div><div><label>Usuario de MySQL</label><input name="dbuser" required value="<?=h($_POST['dbuser']??'root')?>"></div><div><label>Contraseña de MySQL (vacía si no configuraste una)</label><input name="dbpassword" type="password" autocomplete="off"></div><div><label>Correo del administrador</label><input name="adminemail" type="email" required value="<?=h($_POST['adminemail']??'admin@nobel.edu.pe')?>"></div></div><label>Contraseña del administrador (al menos 8 caracteres)</label><input name="adminpassword" type="password" minlength="8" required autocomplete="new-password"><button class="button">Crear base de datos e instalar →</button></form><?php endif; ?></main><script src="assets/accessibility.js?v=20261023" defer></script></body></html>
